'use strict';
/**
 * @generated-source (this script generates bridge.gen.d.ts)
 * 从 src/shared/ipcContract.js 生成渲染层 bridge 的精确 TypeScript 类型。
 *
 * 用法：node scripts/gen-bridge-types.js
 * 输出：src/renderer/app/core/bridge.gen.d.ts
 */
const fs = require('fs');
const path = require('path');

const { CHANNELS, METHODS, EVENTS } = require('../src/shared/ipcContract.js');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'src', 'renderer', 'app', 'core', 'bridge.gen.d.ts');

/** @param {any} spec */
function tsType(spec) {
  if (!spec || typeof spec !== 'object') return 'unknown';
  switch (spec.k) {
    case 'str':
      return 'string';
    case 'int':
      return 'number';
    case 'bool':
      return 'boolean';
    case 'enum': {
      const vals = Array.isArray(spec.values) ? spec.values : [];
      if (vals.length === 0) return 'string';
      return vals.map((v) => JSON.stringify(v)).join(' | ');
    }
    case 'obj':
      return 'Record<string, unknown>';
    case 'arr':
      return 'unknown[]';
    case 'shape': {
      const fields = spec.fields && typeof spec.fields === 'object' ? spec.fields : {};
      const required = new Set(Array.isArray(spec.required) ? spec.required : []);
      const keys = Object.keys(fields);
      if (keys.length === 0) return 'Record<string, unknown>';
      const parts = keys.map((k) => {
        const opt = required.has(k) ? '' : '?';
        return `${JSON.stringify(k)}${opt}: ${tsType(fields[k])}`;
      });
      return `{ ${parts.join('; ')} }`;
    }
    case 'any':
    default:
      return 'unknown';
  }
}

/** @param {string} channel */
function methodSignature(channel) {
  const entry = CHANNELS[channel];
  const args = entry && Array.isArray(entry.args) ? entry.args : [];
  if (args.length === 0) return '() => Promise<unknown>';
  const params = args.map(([name, spec], i) => {
    const safe = /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : `arg${i}`;
    return `${safe}?: ${tsType(spec)}`;
  });
  return `(${params.join(', ')}) => Promise<unknown>`;
}

function generate() {
  const methodKeys = Object.keys(METHODS).sort();
  const eventKeys = Object.keys(EVENTS).sort();

  const methodLines = methodKeys.map((m) => {
    const ch = METHODS[m];
    return `  ${JSON.stringify(m)}: ${methodSignature(ch)};`;
  });

  const eventLines = eventKeys.map((e) => {
    return `  ${JSON.stringify(e)}: (cb: (...args: unknown[]) => void) => (() => void) | void;`;
  });

  const out = `// @generated by scripts/gen-bridge-types.js — do not edit by hand
// Source of truth: src/shared/ipcContract.js (METHODS / EVENTS / CHANNELS.args)
// Regenerate: node scripts/gen-bridge-types.js

export interface BridgeMethods {
${methodLines.join('\n')}
}

export interface BridgeEvents {
${eventLines.join('\n')}
}

export type BridgeMethodName = keyof BridgeMethods;
export type BridgeEventName = keyof BridgeEvents;
`;

  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, out, 'utf8');
  console.log(`Generated ${path.relative(ROOT, OUT)} (${methodKeys.length} methods, ${eventKeys.length} events)`);
}

generate();
